insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('kurtis-blow','Kurtis Blow','Kurtis Blow',1980,'1980s','Mercury Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Old-school hip-hop','Disco rap']::text[],null,'<p>The cover of Kurtis Blow''s debut is a straightforward portrait of the rapper with his name as the title. That plainness was the point. This was one of the first full-length rap albums released by a major label, and Mercury Records sold it the way it sold any new singer: the face, the name and nothing to get in the way. The record was produced by J. B. Moore and Robert Ford Jr., with management credited to Rush Productions, the company run by a young Russell Simmons.</p><p>Blow later explained why he had been picked as the first rapper to get a major deal. Asked why the industry chose him over his peers, he said it was "because I was a good looking guy." The sleeve makes that case without words. Hip-hop in 1980 was still mostly a live culture of parks, clubs and mixtapes, and very few people outside New York knew what a rapper looked like. A clean studio portrait introduced one to the rest of the country as a star in the mould of the soul and disco acts in the same record racks.</p><p>The success of "The Breaks", a gold single, had convinced Mercury that Blow was more than a novelty, and the album followed. Its cover set a template that rap debuts would use for years: the artist alone, named in large type, presented as a solo celebrity. The album was released on 29 September 1980.</p>',null,'published','2026-10-31T06:00:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('escape','Escape','Whodini',1984,'1980s','Jive Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['Old-school hip-hop','Electro']::text[],null,'<p>The cover of Escape shows the two rappers of Whodini, Jalil Hutchins and John "Ecstasy" Fletcher, photographed behind a set of bars. The jail-cell framing is a direct visual reading of the title, and it made the second album by the Brooklyn group easy to understand at a glance. It was released by Jive Records, the American arm of Zomba, which had signed the group early and used London-based production to give them a polished electro sound.</p><p>The bars are a playful idea. Whodini were known for witty, adult storytelling about nightlife and relationships, and the image of two sharply dressed young men locked up, looking for a way out, matches the album''s mood of escape from everyday pressure. The photograph also left someone out. As one retrospective noted, it was the second Whodini album in a row to "disrespectfully omit the third member and group deejay, Grandmaster D, from the album cover." The decision kept the focus on the two voices that radio listeners knew.</p><p>Escape became Whodini''s most successful record, carried by "Friends", "Big Mouth" and "Five Minutes of Funk", and it helped prove that a rap group could sell albums as well as twelve-inch singles. The barred cover is now one of the defining images of the group''s peak. Ecstasy died in 2020. The album was released on 17 October 1984.</p>',null,'published','2026-10-31T05:23:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('criminal-minded','Criminal Minded','Boogie Down Productions',1987,'1980s','B-Boy Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Hardcore hip-hop']::text[],null,'<p>The front of Criminal Minded shows the two members of Boogie Down Productions, KRS-One and DJ Scott La Rock, sitting at a table holding guns, with ammunition on display. The title runs across the top and the group''s name across the bottom. On the back cover the scene continues: the same two men at a table, one on the phone and the other pointing a gun, with the track list and credits arranged around them. The record came out on B-Boy Records, a small independent label in the Bronx.</p><p>XXL later wrote that this "was the first time rappers were holding firearms on the cover of a major hip-hop release." The group insisted the weapons stood for self-defence and militancy. KRS-One explained the image in political terms: "If you look at the cover of Criminal Minded, that''s what we were saying modern-day Black Panthers are." The pose borrows from the armed portraits of the Black Panther Party, transplanted to a table in the South Bronx.</p><p>The photograph became a blueprint. Within a few years guns were common on rap covers, often without the political framing BDP had claimed. Its meaning also changed quickly and painfully: Scott La Rock was shot and killed on 27 August 1987, months after the album appeared, and the image of him armed took on a grim second reading. The album was released on 3 March 1987.</p>',null,'published','2026-10-31T04:46:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('yo-bum-rush-the-show','Yo! Bum Rush the Show','Public Enemy',1987,'1980s','Def Jam Recordings, Columbia','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Political hip-hop']::text[],'Art direction by Eric Haze; photography by Glen E. Friedman','<p>Public Enemy''s debut cover is a dark, close group photograph shot by Glen E. Friedman in a basement studio. Chuck D says it was taken "downstairs in Eric Sadler''s studio" at 510 South Franklin in Hempstead, Long Island, the group''s home base. The sleeve credits the cover concept to Carl Ryder, Chuck D''s pseudonym, and Friedman together, with art direction by the graffiti artist and designer Eric Haze, who also cleaned up the logo Chuck had drawn himself.</p><p>The image started on paper. "It actually came off of a drawing that I drew," Chuck D recalled, and Friedman set the scene up from his sketch. The group wanted the photograph to feel like a war room, with the crew "conjuring a plan and looking at blueprints." Chuck''s instruction was blunt: "This is dead serious." Of everyone in the frame, he said, Flavor Flav "probably got the most menacing looking period on that cover." The group picked the final frame together from a proof sheet. The back cover was shot at a Hempstead McDonald''s that no longer exists.</p><p>The cover announced a different kind of rap group: organised, political and unsmiling, a long way from the party imagery of earlier rap sleeves. Friedman went on to shoot more for the group, and the Haze logo became part of its identity. The album was released on 10 February 1987.</p>',null,'published','2026-10-31T04:09:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('eric-haze','Eric Haze','Art Director') on conflict (slug) do nothing;
