insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'yo-bum-rush-the-show' and c.slug = 'glen-e-friedman' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('all-hail-the-queen','All Hail the Queen','Queen Latifah',1989,'1980s','Tommy Boy Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Conscious hip-hop']::text[],null,'<p>The cover of All Hail the Queen is a portrait of Queen Latifah in a power stance, dressed in black with a black headscarf and gold stripes on her sleeves. The palette is mostly black with flashes of gold, a regal colour scheme that matches the title. The album was released by Tommy Boy Records when Latifah was nineteen, after her first singles had built a following in New York.</p><p>The styling was a statement. In a 1989 interview on Yo! MTV Raps, Latifah explained that she preferred African clothing and accessories because buying them supported African businesses and made her feel closer to her ancestors. "I just feel inner power," she said. The headwrap and gold trim belong to that Afrocentric moment in late-1980s hip-hop, when artists around the Native Tongues collective were putting African dress and history at the centre of their image. Her name already claimed royalty, and in her first video she wore a crown that became a trademark. On the cover she needs no crown: posture and colour do the work.</p><p>At a time when women in rap were often styled as sidekicks or sex symbols, the image presented a young woman as a sovereign figure on her own terms. It fits the album''s best-known song, "Ladies First", recorded with Monie Love. The album was released on 28 November 1989.</p>',null,'published','2026-10-31T03:32:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('amerikkka-s-most-wanted','AmeriKKKa''s Most Wanted','Ice Cube',1990,'1990s','Priority Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['West Coast hip-hop','Gangsta rap']::text[],'Art direction by Kevin Hosmann; photography by Mario Castellanos','<p>Ice Cube''s first solo album after leaving N.W.A put him at the centre of its cover, photographed by Mario Castellanos with art direction by Kevin Hosmann for Priority Records. The record was made far from Los Angeles, at Greene Street Studios in New York with Public Enemy''s production team, the Bomb Squad, and the packaging reflects that mix of West Coast attitude and East Coast politics.</p><p>The words do as much work as the picture. The title is a play on America''s Most Wanted, the true-crime television show hosted by John Walsh that asked viewers to help catch fugitives. Spelling America with three Ks turns the country itself into the Klan, and casts Ice Cube as the fugitive the nation is hunting. The sleeve frames him as a wanted man in a country he accuses of being the real criminal. The back cover kept up the confrontation in its own way: on one track title the words "Dick" and "Bitch" were blacked out, while the inner sleeve printed them in full.</p><p>The cover sold the idea of Ice Cube as public enemy number one only a month after Public Enemy''s Fear of a Black Planet, and the album went on to become a landmark of political gangsta rap. Its triple-K spelling became a template for protest titles in rap and beyond. The album was released on 16 May 1990.</p>',null,'published','2026-10-31T02:55:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('kevin-hosmann','Kevin Hosmann','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'amerikkka-s-most-wanted' and c.slug = 'kevin-hosmann' on conflict do nothing;
insert into public.creators (slug,name,role) values ('mario-castellanos','Mario Castellanos','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'amerikkka-s-most-wanted' and c.slug = 'mario-castellanos' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('breaking-atoms','Breaking Atoms','Main Source',1991,'1990s','Wild Pitch Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Boom bap']::text[],'Art direction by Amy V. Fine; design by Terry Clarke; photography by Peter Bodtke; photographic effects by George Chevalier','<p>The cover of Breaking Atoms places the three members of Main Source, Large Professor and the Toronto brothers K-Cut and Sir Scratch, inside a cosmic scene. The original Wild Pitch sleeve credits the cover concept and design to Terry Clarke, art direction to Amy V. Fine, photography to Peter Bodtke and photographic effects to George Chevalier. Those last credits explain the look: a group portrait reworked with in-camera and darkroom effects until it reads as science fiction.</p><p>The idea follows the title. Breaking atoms is the language of physics and creation, and the image shows the trio as if they were building a universe of their own. The designer Bill McMullen, who later made covers for Beastie Boys and DMX, picked it as one of his favourite rap sleeves of the decade. "These guys are sitting around forming the galaxy," he said. "I just love that fantasy element again." He grouped it with other early-1990s covers that let rap groups be strange and imaginative at a moment when realism was taking over.</p><p>Breaking Atoms is now regarded as a cornerstone of the golden age, the record that introduced Nas on "Live at the Barbeque" and made Large Professor a producer''s producer. Its cover has the same homemade ambition as the music, a small independent label reaching for outer space on a modest budget. The album was released on 23 July 1991.</p>',null,'published','2026-10-31T02:18:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('amy-v-fine','Amy V. Fine','Art Director') on conflict (slug) do nothing;
