insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('daily-operation','Daily Operation','Gang Starr',1992,'1990s','Chrysalis Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Jazz rap']::text[],'Art direction by Marc Cozza; photography by Matt Gunther','<p>The cover of Daily Operation was shot by Matt Gunther, then a young New York photographer, with art direction by Marc Cozza. The crew rented an old mansion on Madison Avenue because they needed a big space. The shoot was booked from 9am to 6pm, but Guru, DJ Premier and an entourage of about twenty arrived at six or seven in the evening. "We slept during the day while waiting for them," Gunther said. He added that the duo "were professionals, no matter how blitzed they were."</p><p>The concept went through several drafts. Guru first wanted a mafioso theme, then a Last Supper scene that would include Group Home and Jeru the Damaja, while the label suggested a Renaissance look. The result blends all three into a tough-guy still life. A portrait of Malcolm X hangs at the top. In the foreground sit a briefcase spilling bundled cash, a globe, a wolf''s head, a Remington Rand typewriter, a skull, a closed turntable case and a paperback of Elijah Muhammad''s Message to the Black Man in America. Guru glares at the lens in a bomber jacket and Premier holds a cigar.</p><p>The designer Bill McMullen said the image "represents exactly the life of Premier and Guru." It has since come to stand for the bond between the two men, which frayed before Guru''s death in 2010. The album was released on 5 May 1992.</p>',null,'published','2026-10-31T01:41:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('marc-cozza','Marc Cozza','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'daily-operation' and c.slug = 'marc-cozza' on conflict do nothing;
insert into public.creators (slug,name,role) values ('matt-gunther','Matt Gunther','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'daily-operation' and c.slug = 'matt-gunther' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('whut-thee-album','Whut? Thee Album','Redman',1992,'1990s','Rush Associated Labels, Def Jam Recordings, Chaos Recordings','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Hardcore hip-hop']::text[],'Art direction and design by The Drawing Board; photography by Timothy Carter','<p>Redman''s debut album carries a photograph by Timothy Carter, with art direction and design by The Drawing Board, the studio that handled much of the visual identity of Def Jam and its affiliated labels in the early 1990s. The record came out through Rush Associated Labels, Def Jam and Chaos Recordings, a Columbia imprint, with Erick Sermon of EPMD as executive producer. The original vinyl came with a black and white printed inner sleeve carrying credits, a graphic and a photo.</p><p>The title tells you what kind of package this is. Whut? reads like a voice from the back of the room, and the spelling of Thee Album is a joke at the expense of serious debut records. Redman arrived from Newark as part of Sermon''s Hit Squad, with a reputation for wild humour, horror-movie skits and funk samples, and the cover had to introduce a rapper whose persona was as important as his rhymes. The Drawing Board''s design kept the focus on Redman himself, letting Carter''s photograph carry the personality.</p><p>The album went gold and set up a run of Redman records that leaned further into dark comedy and psychedelic funk. The title format proved durable too: he returned to it in 2007 with Red Gone Wild: Thee Album, and the debut has since been reissued on vinyl. The album was released on 22 September 1992.</p>',null,'published','2026-10-31T01:04:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('the-drawing-board','The Drawing Board','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'whut-thee-album' and c.slug = 'the-drawing-board' on conflict do nothing;
insert into public.creators (slug,name,role) values ('the-drawing-board','The Drawing Board','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'whut-thee-album' and c.slug = 'the-drawing-board' on conflict do nothing;
