insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'whut-thee-album' and c.slug = 'timothy-carter' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('black-sunday','Black Sunday','Cypress Hill',1993,'1990s','Ruffhouse Records, Columbia Records','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['West Coast hip-hop','Latin hip-hop']::text[],'Art direction by Pawn Shop Press; design by Dante Ariola and Jay Papke; photography by Anthony Artiaga','<p>The cover of Black Sunday is a horror scene: a hill built from skulls and graves under the silhouette of a spooky tree, with the title in gothic lettering. The original Ruffhouse and Columbia gatefold credits art direction and the logo to Pawn Shop Press, the design concept and design to Dante Ariola and Jay Papke, and photography to Anthony Artiaga. The vinyl came with printed black and white inner sleeves.</p><p>The image is a visual pun on the group''s name. A lone tree on a hill of bones is a literal, gothic Cypress Hill, named after Cypress Avenue in South Gate, recast as a graveyard. It extends the morbid humour of their debut, whose songs were full of shootings and threats, and matches the album''s darker sound, from the menace of "I Ain''t Goin'' Out Like That" to the stoned swagger of "Insane in the Brain". The gothic type and graveyard tone owe more to horror films and metal sleeves than to rap tradition, which suited a group that was already crossing into rock audiences.</p><p>Black Sunday entered the Billboard 200 at number one, and its skull-hill imagery became part of the band''s lasting visual identity. Thirty years on, the cover was still recognisable enough for Cypress Hill to build a graphic novel and anniversary concerts around the album''s title. The album was released on 20 July 1993.</p>',null,'published','2026-10-31T00:27:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('pawn-shop-press','Pawn Shop Press','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'black-sunday' and c.slug = 'pawn-shop-press' on conflict do nothing;
insert into public.creators (slug,name,role) values ('dante-ariola','Dante Ariola','Designer') on conflict (slug) do nothing;
