insert into public.creators (slug,name,role) values ('jay-papke','Jay Papke','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'black-sunday' and c.slug = 'jay-papke' on conflict do nothing;
insert into public.creators (slug,name,role) values ('anthony-artiaga','Anthony Artiaga','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'black-sunday' and c.slug = 'anthony-artiaga' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('the-sun-rises-in-the-east','The Sun Rises in the East','Jeru the Damaja',1994,'1990s','Payday Records, FFRR','United States','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['East Coast hip-hop','Boom bap']::text[],'Art direction and photography by Danny Hastings; painting by Hugo Bravo','<p>The cover of The Sun Rises in the East combines a photograph and a painting. Jeru the Damaja sits at the ready in the foreground while the Manhattan skyline burns in red and orange behind him, the World Trade Center in flames and the Statue of Liberty floating in the river. The art director and photographer Danny Hastings shot Jeru, then brought in the illustrator Hugo Bravo. "Danny said he wanted to combine an illustration with his photo for the cover," Bravo recalled. Bravo painted the city in oil on illustration board.</p><p>Hastings took his starting point from the film Escape from New York, with its ruined Manhattan, and the metaphor was simple: Jeru would beat every rival in a rap battle and be the last man standing. Bravo based the details on a line about the World Trade Center in "Come Clean". His first pen sketch went further, with the South Street Seaport burning and the Brooklyn Bridge collapsed. Hastings showed the concept to Jeru and his team, and Bravo got the go-ahead to paint.</p><p>The album arrived one year after the 1993 bombing of the World Trade Center, and Sotheby''s later called the image "a bold and foreboding choice for an album cover." Seen after September 2001, it carries a weight nobody intended. Bravo''s painting, sketch and Hastings''s signed print were later offered at a Sotheby''s hip-hop sale. The album was released on 24 May 1994.</p>',null,'published','2026-10-30T23:50:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('danny-hastings','Danny Hastings','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'the-sun-rises-in-the-east' and c.slug = 'danny-hastings' on conflict do nothing;
insert into public.creators (slug,name,role) values ('danny-hastings','Danny Hastings','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'the-sun-rises-in-the-east' and c.slug = 'danny-hastings' on conflict do nothing;
insert into public.creators (slug,name,role) values ('hugo-bravo','Hugo Bravo','Painter') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'the-sun-rises-in-the-east' and c.slug = 'hugo-bravo' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('ironman','Ironman','Ghostface Killah',1996,'1990s','Razor Sharp Records, Epic Street','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Mafioso rap']::text[],'Design and illustration by Ron Croudy; photography by Michael Lavine and Sophia Chang','<p>Ghostface Killah''s first solo album is credited to him alone, but he does not stand alone on the cover. Raekwon and Cappadonna share the front with him, in face and in name, so the sleeve reads almost as a trio record. The original US release on Razor Sharp and Epic Street credits design and illustration to Ron Croudy and photography to Michael Lavine, with additional portraits by Sophia Chang, credited on the sleeve as "Ill Portraits".</p><p>The shared cover reflects how the album was made. It came a year after Raekwon''s Only Built 4 Cuban Linx, on which Ghostface had been the essential second voice, and Ironman returned the favour, with Raekwon and Cappadonna rapping on many of its tracks. Putting three faces on the front was honest packaging for a Wu-Tang record built on chemistry, and it sold the Ghostface, Raekwon and Cappadonna partnership as a unit. The title came from the Marvel hero Iron Man, one of several comic-book aliases Ghostface used, and the illustrated design gives the sleeve a little of that comic-book feel.</p><p>Lavine, a New York portrait photographer best known for his early photographs of Nirvana, also shot The Notorious B.I.G.''s Life After Death the following year and returned for Ghostface''s Supreme Clientele in 2000. Ironman debuted at number two on the Billboard 200. The album was released on 29 October 1996.</p>',null,'published','2026-10-30T23:13:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('ron-croudy','Ron Croudy','Designer') on conflict (slug) do nothing;
