insert into public.creators (slug,name,role) values ('jonathan-mannion','Jonathan Mannion','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'it-s-dark-and-hell-is-hot' and c.slug = 'jonathan-mannion' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('supreme-clientele','Supreme Clientele','Ghostface Killah',2000,'2000s','Razor Sharp Records, Epic Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['East Coast hip-hop','Abstract hip-hop']::text[],'Art direction by Brian Freeman and John Carr; photography by Michael Lavine','<p>The cover of Supreme Clientele is a photograph of Ghostface Killah by Michael Lavine, with art direction by Brian Freeman and John Carr. It was Lavine''s second Ghostface sleeve after Ironman. The New York portrait photographer had made his name with early images of Nirvana and the Seattle scene, and had also shot The Notorious B.I.G.''s Life After Death. On this record Ghostface appears alone, a change from Ironman, where he shared the front with Raekwon and Cappadonna.</p><p>The solo cover suits the album. Supreme Clientele was Ghostface''s statement of independence at a low point for Wu-Tang Clan, and it is built around his own dense, abstract storytelling. The packaging carries some of that oddness. The original CD had a sparkly silver inner tray, and it printed two different fourteen-song track lists, one on the back cover and one in the booklet. Some editions of the liner notes even list a song under another name. The confusion feels in keeping with lyrics that often make sense only by sound and feeling.</p><p>The album was widely hailed as a return to form for the Wu-Tang camp, and it has grown into one of the most admired solo records any member of the group made. Its packaging quirks have become collector lore. The album was released on 8 February 2000.</p>',null,'published','2026-10-30T21:59:00+00:00') on conflict (slug) do nothing;
