insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'supreme-clientele' and c.slug = 'michael-lavine' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('miss-e-so-addictive','Miss E... So Addictive','Missy Elliott',2001,'2000s','The Goldmind Inc. / Elektra Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Hip-hop','Dance']::text[],null,'<p>The cover of Miss E... So Addictive is a portrait of Missy Elliott. The Source, looking back on the record, noted that she "sported a more glamorous look along with a new hair do" for the sleeve.</p><p>That restraint was a choice. By 2001 Missy Elliott was known as one of the most inventive image makers in pop, the rapper who had worn an inflated plastic suit and filmed herself in fish-eye distortion. On the sleeve of her third album she chose a glamorous portrait. The title promised a drug, and the photograph sells the star herself as the habit, polished and direct, with the playful strangeness held back for the records inside. The music, led by the single "Get Ur Freak On", pushed further into club rhythms and global sounds than anything she had made before, and the glossy cover gave that ambition a confident public face.</p><p>The album became one of the defining hip-hop records of its year and carried Missy Elliott further into the mainstream. Its cover is less discussed than her videos, yet it marks the moment she presented herself as a headline pop star on her own terms. Miss E... So Addictive was released on 15 May 2001.</p>',null,'published','2026-10-30T21:22:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('nellyville','Nellyville','Nelly',2002,'2000s','Universal Records / Fo'' Reel Entertainment','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Southern hip-hop','Pop rap']::text[],'Art direction by Sandy Brummels; design by Robert Sims; photography by Jonathan Mannion','<p>The cover of Nellyville presents Nelly at the height of his fame, photographed by Jonathan Mannion, the New York photographer behind many of the era''s defining rap sleeves. The package was put together at Universal, with artwork credited to Sandy Brummels and design by Robert Sims. Mannion has named Nelly among the stars he worked with early in his career, alongside Jay-Z, DMX and Ja Rule.</p><p>The title gives the image its frame. Nellyville is an imagined town, a St. Louis of the mind where Nelly sets the rules, and the album turns his home city into a brand. St. Louis Magazine described the record as a world "filled with decadence, luxury, and, of course, St. Louis." The cover sells that idea through its star: two years after Country Grammar made him a national name, Nelly is shown as the mayor of his own place, confident and camera ready, the face of a city that had rarely been heard in rap before him.</p><p>Nellyville became one of the biggest albums of 2002, carried by "Hot in Herre" and "Dilemma", and its cover became a familiar sight in record shops that summer. The album did not appear on vinyl until a 2LP reissue from UMe and Republic on 29 July 2022, twenty years on. The album was first released on 25 June 2002.</p>',null,'published','2026-10-30T20:45:00+00:00') on conflict (slug) do nothing;
