insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('diplomatic-immunity','Diplomatic Immunity','The Diplomats',2003,'2000s','Roc-A-Fella Records / Diplomat Records / Island Def Jam','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Chipmunk soul']::text[],'Art direction by Akisia Grigsby; photography by Jonathan Mannion','<p>Diplomatic Immunity introduced The Diplomats as a unit, and its cover is a portrait of the Harlem crew together. The photograph is by Jonathan Mannion, who had shot many of Roc-A-Fella''s defining covers, with art direction by Akisia Grigsby. It was the only album the group released through Roc-A-Fella and Island Def Jam, and the sleeve carries the confidence of that moment.</p><p>The title is the joke and the thesis. Diplomatic immunity is the legal shield that lets envoys break local laws without consequence, and Cam''ron, Jim Jones, Juelz Santana and Freekey Zekey styled themselves as exactly that: a delegation from Harlem, above the rules. The crew photograph turns the idea into a group statement of loyalty. Mannion''s job across this period was to make rap stars look like they already owned the room, and here he applies that to a whole crew, presenting them as a single front before most of the country knew their names.</p><p>The double album was delayed twice from early March before it finally appeared, and it became a cult text for New York rap, its sped-up soul samples and slang copied for years. The image of the crew together grew more poignant as the group fractured and reunited over the following two decades. Diplomatic Immunity was released on 25 March 2003.</p>',null,'published','2026-10-30T19:31:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('akisia-grigsby','Akisia Grigsby','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'diplomatic-immunity' and c.slug = 'akisia-grigsby' on conflict do nothing;
insert into public.creators (slug,name,role) values ('jonathan-mannion','Jonathan Mannion','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'diplomatic-immunity' and c.slug = 'jonathan-mannion' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('vaudeville-villain','Vaudeville Villain','Viktor Vaughn',2003,'2000s','Sound-Ink Records / Traffic Entertainment Group','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Underground hip-hop','Alternative hip-hop']::text[],'Art direction by M. McDonald; design by Ralph Borland','<p>Vaudeville Villain is an MF DOOM album in disguise, and its cover introduces the disguise. The sleeve presents Viktor Vaughn, the masked alter ego DOOM created for the record, with art direction credited to M. McDonald and layout and design to Ralph Borland. It was released by the small New York label Sound-Ink, a long way from the major-label machinery of most rap covers of the time.</p><p>The name is a comic-book pun. Viktor Vaughn is a play on Victor Von Doom, the Marvel villain whose metal face inspired DOOM''s own mask, and the album casts him as a young, time-travelling hustler stranded in early-1990s New York, scheming to raise money to fix his broken machine. Glide Magazine called him "the most colorful and innovative alter-ego" of DOOM''s career. The cover had to do a strange job: sell a new character played by a man who never showed his face. The title adds a second layer, borrowing the language of old variety theatre, where performers played stock villains for a paying crowd, a fair description of DOOM''s whole approach to persona.</p><p>The album arrived in the same busy run that produced Madvillainy and MM..Food, and it has since been reissued on coloured vinyl, keeping its cover in record shops two decades on. Vaudeville Villain was released on 16 September 2003.</p>',null,'published','2026-10-30T18:54:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('m-mcdonald','M. McDonald','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'vaudeville-villain' and c.slug = 'm-mcdonald' on conflict do nothing;
insert into public.creators (slug,name,role) values ('ralph-borland','Ralph Borland','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'vaudeville-villain' and c.slug = 'ralph-borland' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('let-s-get-it-thug-motivation-101','Let''s Get It: Thug Motivation 101','Young Jeezy',2005,'2000s','Corporate Thugz Entertainment / Def Jam Recordings','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Southern hip-hop','Trap']::text[],null,'<p>The cover of Let''s Get It: Thug Motivation 101 is a portrait of Young Jeezy on the brink of stardom, the Atlanta rapper''s major-label debut after years of street mixtapes. It was released through Def Jam and his own Corporate Thugz imprint, and the sleeve presents him as the record''s title promises: a motivational speaker for hustlers, staring straight back at the buyer.</p><p>The image sits inside a wider visual world that Jeezy built around the album. The most famous part of it never appeared on the cover: the snowman, the cartoon logo that spread across T-shirts in 2005 and carried an open drug reference. Jeezy later recalled Samuel L. Jackson telling him that "the snowman represents people that were demonized." The cover leaves the symbol to the merchandise and puts the man in front, which suited a record built on persona and ad-lib as much as on verses. The course-number title, 101, borrows the language of college to frame street knowledge as a curriculum.</p><p>The album helped set the template for trap music as a mainstream genre, and Jeezy returned to the title for Thug Motivation 102 and 103, keeping the brand alive across a decade. He marked its twentieth anniversary with an orchestral show and a tour in 2025. Let''s Get It: Thug Motivation 101 was released on 26 July 2005.</p>',null,'published','2026-10-30T18:17:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('hell-hath-no-fury','Hell Hath No Fury','Clipse',2006,'2000s','Re-Up Gang / Star Trak / Jive Records (Zomba)','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['East Coast hip-hop','Coke rap']::text[],'Art direction and design by Courtney Walter; photography by Jonathan Mannion','<p>The cover of Hell Hath No Fury is a portrait of Clipse, the Virginia Beach brothers Pusha T and Malice, photographed by Jonathan Mannion. Courtney Walter handled art direction and design. Mannion had shot many of the defining rap sleeves of the previous decade, and here he applies his direct, unfussy approach to a duo whose music was famously cold and exact.</p><p>The image carries the weight of a long wait. Recording began in late 2003, then stalled in 2004 when the Sony BMG merger moved Clipse from Arista to Jive. The brothers wanted to follow The Neptunes'' Star Trak label, Jive refused, and two years of lawsuits and delays followed. By the time the album appeared, its title read as a message to the label as much as a proverb. The sleeve does not dress up that anger. It presents the two brothers as they were, which fitted a record about the drug trade told without glamour or apology, with production by The Neptunes stripped to bare drums and metal.</p><p>Jive did little to promote the album, yet critics placed it among the best records of 2006 and its standing has only grown since. The duo and the label agreed to part in 2007. Hell Hath No Fury was released on 28 November 2006.</p>',null,'published','2026-10-30T17:40:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('courtney-walter','Courtney Walter','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'hell-hath-no-fury' and c.slug = 'courtney-walter' on conflict do nothing;
insert into public.creators (slug,name,role) values ('jonathan-mannion','Jonathan Mannion','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'hell-hath-no-fury' and c.slug = 'jonathan-mannion' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('lupe-fiasco-s-food-and-liquor','Lupe Fiasco''s Food & Liquor','Lupe Fiasco',2006,'2000s','1st & 15th Entertainment / Atlantic Records','United States','464ed954-6e08-4d0e-84ab-1a736b658cd3',array['Conscious hip-hop','Alternative hip-hop']::text[],'Design by Chuck Anderson and Righteous Kung Fu','<p>The cover of Lupe Fiasco''s Food & Liquor shows the Chicago rapper floating in mid-air, surrounded by the objects of his daily life: a Banksy postcard, a Nintendo DS, a sketchbook, a copy of the Qur''an and a toy robot. It was designed by Chuck Anderson, the Chicago artist behind the studio No Pattern, working with Righteous Kung Fu. Its bright, sliced light and sense of motion belong to the digital illustration style that Anderson was known for in the mid-2000s.</p><p>The starting point was a skateboard deck Lupe owned, and the objects were chosen because they were things he carried around every day. Together they make a self-portrait in possessions: faith, art, games and street culture held in the same orbit. Looking back for the album''s tenth anniversary, Lupe tied the light effects to the work of the Japanese manga artist Katsuhiro Otomo, the creator of Akira. The liner notes extend the idea with gentle parody, replacing liquor with milk and cookies in a scene of drug dealing and swapping guns for books in a drive-by.</p><p>The cover marked Lupe as something new in mainstream rap, a skater and anime fan on a major label, and its blend of graphic design and photography anticipated the look of much blog-era hip-hop. Lupe Fiasco''s Food & Liquor was released on 19 September 2006.</p>',null,'published','2026-10-30T17:03:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('chuck-anderson','Chuck Anderson','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'lupe-fiasco-s-food-and-liquor' and c.slug = 'chuck-anderson' on conflict do nothing;
insert into public.creators (slug,name,role) values ('righteous-kung-fu','Righteous Kung Fu','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'lupe-fiasco-s-food-and-liquor' and c.slug = 'righteous-kung-fu' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('king','King','T.I.',2006,'2000s','Grand Hustle Records / Atlantic Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Southern hip-hop','Trap']::text[],'Art direction by Greg Gigendad Burke; design by Greg Gigendad Burke and Sean Donnelly; photography by Christian Lantry','<p>The cover of King is a portrait of T.I., photographed by Christian Lantry, with art direction and design by Greg Gigendad Burke and further design by Sean Donnelly. Robert Gold produced the shoot. It was T.I.''s fourth album and his biggest release yet on Grand Hustle and Atlantic, and the sleeve treats the occasion as a coronation, with the one-word title doing most of the talking.</p><p>The word had history. Five years earlier, when his debut was selling modestly, T.I. had declared himself the "King of the South", a claim that was bold for a rapper with no hits to his name. By 2006 the hits had caught up with the boast, and the cover states it plainly. There is no throne room or crown jewels in the title, just the name of the office and the face of the man who claimed it. The design keeps the attention on T.I. himself, with little to distract from the face and the title.</p><p>The album debuted at number one with more than 500,000 copies in its first week, the biggest debut of the year at that point, while his starring role in the film ATL opened in cinemas. XXL later wrote that by the end of the year he "wasn''t just the king of the South, he was the king of rap." King was released on 28 March 2006.</p>',null,'published','2026-10-30T16:26:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('greg-gigendad-burke','Greg Gigendad Burke','Art Director') on conflict (slug) do nothing;
