insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'king' and c.slug = 'christian-lantry' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('teflon-don','Teflon Don','Rick Ross',2010,'2010s','Maybach Music Group / Slip-n-Slide Records / Def Jam Recordings','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Southern hip-hop','Mafioso rap']::text[],null,'<p>The cover of Teflon Don is a portrait of Rick Ross, the Miami rapper presented as the boss his title describes. It was his fourth album, released through his own Maybach Music Group with Slip-n-Slide and Def Jam, and the sleeve continues the image he had been building since his debut: a heavyset, bearded figure who carried himself like the head of a crime family.</p><p>The title comes from the nickname the New York press gave John Gotti, the Gambino boss whose criminal charges seemed never to stick. Ross borrowed the phrase at a pointed moment. In 2008 it had been revealed that he once worked as a corrections officer, a story that many expected to end his career. It did not, and the Teflon label became his reply: nothing landed on him either. The portrait plays the part straight. There is no wink in it, which is how Ross''s persona worked: a fantasy of power performed with total seriousness. uDiscover Music later described the album as the moment Ross "lived up to his mafia moniker."</p><p>Teflon Don, with "B.M.F. (Blowin'' Money Fast)" and "Aston Martin Music", became one of the most acclaimed records of his career, and the cover''s luxury-boss imagery set the tone for the Maybach Music era that followed. It was released on 20 July 2010.</p>',null,'published','2026-10-30T15:49:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('sir-lucious-left-foot-the-son-of-chico-dusty','Sir Lucious Left Foot: The Son of Chico Dusty','Big Boi',2010,'2010s','Purple Ribbon Records / Def Jam Recordings','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Southern hip-hop','Funk']::text[],'Art direction and design by Alex Haldi; photography by Jonathan Mannion','<p>The cover of Big Boi''s first solo album is a portrait by Jonathan Mannion, who shot both the cover and the interior photographs. Art direction and graphic design were by Alex Haldi of the studio Bestest Asbestos, with art and photography coordination by Tai Linzie and package production by Doug Joswick. It was released through Big Boi''s Purple Ribbon imprint and Def Jam.</p><p>The pairing had history. Seven years earlier Mannion had photographed Big Boi for Speakerboxxx, building that cover by hand with speaker boxes, record crates and a live rooster. Sir Lucious Left Foot is one of Big Boi''s long-running alter egos, so the solo album picks up a character his fans already knew. The subtitle adds a family tie, presenting him as the son of Chico Dusty. The road to release was long. Big Boi had recorded the album at Jive, where, he said, the label told him "This is a piece of art, and we don''t know what to do with it." When Jive suggested he cover Lil Wayne''s "Lollipop", he left for Def Jam.</p><p>The album was released to strong reviews, and limited editions came with an alternative double-LP cover, ivory vinyl and a custom chain. Big Boi also designed a run of Converse Chuck Taylors with the title on the heel. Sir Lucious Left Foot: The Son of Chico Dusty was released in the US on 6 July 2010.</p>',null,'published','2026-10-30T15:12:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('alex-haldi','Alex Haldi','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'sir-lucious-left-foot-the-son-of-chico-dusty' and c.slug = 'alex-haldi' on conflict do nothing;
