insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'sir-lucious-left-foot-the-son-of-chico-dusty' and c.slug = 'jonathan-mannion' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('section-80','Section.80','Kendrick Lamar',2011,'2010s','Top Dawg Entertainment','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['Conscious hip-hop','West Coast hip-hop']::text[],'Design by Hassana Lynne; photography by Dave Free','<p>The cover of Section.80 is a dim, cluttered scene from the Compton of Kendrick Lamar''s youth. Among the objects in the frame are a Bible, a gun clip, pills and money, the furniture of a life lived between temptation and faith. It was photographed by Dave Free, Kendrick''s childhood friend and later his creative partner at pgLang, and designed by Hassana Lynne. Top Dawg Entertainment unveiled the artwork on 29 June 2011, three days before the album''s release.</p><p>Kendrick explained the image to iTunes in 2012 as a picture of the "taboos of the world." The objects work like a still life with a moral: scripture next to ammunition, medicine next to cash, the choices a young person in the city is offered every day. The album''s title refers to Section 8 housing and to the generation born in the 1980s, the children of the crack era, and the cover gives that generation''s surroundings a physical form. It is a home-made image in the best sense, shot by a friend who knew the world it showed.</p><p>Section.80 was released independently and sold mainly through iTunes, yet it put Kendrick on the path to Good Kid, M.A.A.D City a year later. The partnership with Dave Free continued through every major release that followed. Section.80 was released on 2 July 2011.</p>',null,'published','2026-10-30T14:35:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('hassana-lynne','Hassana Lynne','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'section-80' and c.slug = 'hassana-lynne' on conflict do nothing;
insert into public.creators (slug,name,role) values ('dave-free','Dave Free','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'section-80' and c.slug = 'dave-free' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('goblin','Goblin','Tyler, the Creator',2011,'2010s','XL Recordings','United States','dad05a73-56a1-4791-ba0a-64cfbc2ad929',array['Alternative hip-hop','Horrorcore']::text[],'Design by Tyler, the Creator','<p>Tyler, the Creator is nowhere on the standard cover of Goblin. The image is a recoloured nineteenth-century portrait of William "Buffalo Bill" Cody, taken when the showman was 19, the same age Tyler was when the album came out. Tyler designed the sleeve himself, setting the title in white Cooper Black with a black outline, the same face used on his debut, Bastard. The deluxe edition swapped in a black-and-white photograph of Tyler with an upside-down cross on his forehead, blacked-out eyes and the title in pink across his nose.</p><p>The image arrived as a puzzle. In March 2011 it began appearing in ad slots on music websites, and clicking through led to buffalo-bill.net, which showed the same picture and nothing else. Later the page swapped it for an animated image of the head exploding to reveal the release date. Tyler never explained the choice of Cody, and that silence suits the record: a borrowed face from the American frontier, coloured in by a teenager who liked to provoke, standing in for an album about alter egos and an imaginary therapist.</p><p>The deluxe cover matched the black-and-white world of the "Yonkers" video, and the Cody portrait served as the backdrop for Tyler''s MTV performance. Both covers announced a self-directed artist who would design almost all his own visuals from then on. Goblin was released on 10 May 2011.</p>',null,'published','2026-10-30T13:58:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('tyler-the-creator','Tyler, the Creator','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'goblin' and c.slug = 'tyler-the-creator' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('dreams-and-nightmares','Dreams and Nightmares','Meek Mill',2012,'2010s','Maybach Music Group / Warner Bros. Records','United States','27d91a37-0b27-477a-b65d-82e9697175da',array['East Coast hip-hop','Hardcore hip-hop']::text[],null,'<p>The cover of Dreams and Nightmares reduces Meek Mill''s debut album to a single wrist. A gold Rolex sits on it, and beside the watch is a handcuff. There is no face and no setting, just the two objects sharing the same arm. Meek shared the artwork in early October 2012, a few weeks before the album came out on Maybach Music Group and Warner Bros.</p><p>The idea is stated in the title. The watch stands for the dreams, the money and status of a rapper who had made it out of North Philadelphia, and the cuff stands for the nightmares, the police and courts that had followed him since his teens. Meek told Interview magazine that he wanted the image to carry mixed emotions, "Good times, bad times." The power of the picture is that the two objects are worn together, success and captivity on the same arm. Meek later said he was angry that the handcuffs had to share his wrist with the Rolex.</p><p>Complex ranked it 18th among the best album covers of 2012. Days after release, life echoed the image: police pulled Meek over and detained him on his way to the album''s release party, before letting him go without charge. Years of legal battles followed, which gave the cover a grim prophetic edge. Dreams and Nightmares was released on 30 October 2012.</p>',null,'published','2026-10-30T13:21:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('long-live-asap','Long. Live. A$AP','A$AP Rocky',2013,'2010s','Polo Grounds Music, RCA Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Cloud rap','East Coast hip-hop']::text[],'Creative direction by Virgil Abloh; art direction and design by Joe Perez; photography by Phil Knott','<p>The cover of Long. Live. A$AP shows the Harlem rapper wrapped in an American flag, printed in black and white and broken up as if seen through a glitching VHS tape. The figure appears split in two. The photograph was taken by Phil Knott, and the sleeve was art directed and designed by Joe Perez, a member of Kanye West''s DONDA creative team. Virgil Abloh, then Rocky''s creative director, oversaw the visual world of the release, which also took in stage sets and the "Fashion Killa" video.</p><p>The image followed the monochrome look of Rocky''s 2011 mixtape Live. Love. A$AP, which showed him in a buttoned-up plaid shirt exhaling smoke. On the debut the casual pose gave way to something more monumental. Crack Magazine read the shift in the title too: Long. Live. framed Rocky and the A$AP crew as permanent fixtures. Draining the flag of its red and blue turned a patriotic symbol into a fashion object, in keeping with a rapper who sold himself as much through style as sound.</p><p>Writers placed the cover in a long line of rap records that borrow the flag. The Awl called it "a good cover" and found it "most reminiscent of" OutKast''s Stankonia. The black-and-white scheme stuck: when Rocky revealed the art for At.Long.Last.A$AP in 2015, Billboard noted that it continued the same theme. Knott later sold a print of Rocky at Sotheby''s hip-hop auction in 2020. The album was released on 15 January 2013.</p>',null,'published','2026-10-30T12:44:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('virgil-abloh','Virgil Abloh','Creative Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'long-live-asap' and c.slug = 'virgil-abloh' on conflict do nothing;
insert into public.creators (slug,name,role) values ('joe-perez','Joe Perez','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'long-live-asap' and c.slug = 'joe-perez' on conflict do nothing;
insert into public.creators (slug,name,role) values ('phil-knott','Phil Knott','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'long-live-asap' and c.slug = 'phil-knott' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('acid-rap','Acid Rap','Chance the Rapper',2013,'2010s','Self-released','United States','464ed954-6e08-4d0e-84ab-1a736b658cd3',array['Psychedelic hip-hop','Chicago hip-hop']::text[],'Illustration by Brandon Breaux','<p>The cover of Acid Rap shows Chance the Rapper staring straight out at the viewer, wide-eyed, in a tie-dye tank top, set against a violet sunset sky. It was made by the Chicago artist Brandon Breaux, who also made the cover for Chance''s first mixtape, 10 Day. Breaux worked from a photograph he took himself at South by Southwest in Austin, where Chance performed in a tie-dye top that Breaux had made and given him. The stage lights happened to match the colours of the shirt. Breaux then painted over the image digitally, removing his business partner from the frame.</p><p>Breaux described the idea as the feeling of "someone tripping on acid watching the sun set." He wanted Chance''s face to work like a constellation in the sky, and stars and sky became a signature across his covers. He told The Fader that the record showed Chance "exploring/experimenting." The bugged-out expression and swimming colours made the mixtape''s psychedelic title literal without showing a single drug.</p><p>Acid Rap became the middle panel of a trilogy that closed with Coloring Book in 2016, each cover a tightly composed portrait of Chance against a coloured ground. Breaux said his aim was to "present the work like fine art" at a time when mixtape covers were often throwaway. The approach gave an unsigned artist a visual identity as strong as any major-label campaign. The mixtape was released as a free download on 30 April 2013.</p>',null,'published','2026-10-30T12:07:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('brandon-breaux','Brandon Breaux','Illustrator') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'acid-rap' and c.slug = 'brandon-breaux' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('ds2','DS2','Future',2015,'2010s','A1 Recordings, Freebandz, Epic Records','United States','dad05a73-56a1-4791-ba0a-64cfbc2ad929',array['Trap']::text[],'Photography by Sanja Tošić','<p>The cover of DS2 is a cloud of purple colour blooming through water, with no sign of Future anywhere. The image is a stock photograph titled "Color drop in water, photographed in motion", made by Sanja Tošić, an artist based in Slovenia. It belonged to her "Silky Smooth" series on Shutterstock, and she said the rights were bought by Future''s label, Epic Records, the month before the album came out.</p><p>The swirl reads as an obvious nod to the album''s full title, Dirty Sprite 2, and to the purple codeine mixture that runs through Future''s music. Tošić had no idea who Future was. When The Fader tracked her down on release day, she confirmed the work over Facebook chat: "I''m 110% it''s mine." She would not say what she had been paid, only that her best single sale on the site had earned her $80.00. She added that she had since become a fan and wanted to buy a CD.</p><p>The story became part of the album''s legend. Complex reported that the same picture had already appeared on the cover of a chemistry textbook. Future returned to the stock libraries for later releases, and The Fader traced the cover of EVOL in 2016 to another stock image. A cheap, anonymous photograph ended up fronting one of the defining trap records of the decade. Future posted the cover on 10 July 2015, and the album was released on 17 July 2015.</p>',null,'published','2026-10-30T11:30:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('sanja-tosic','Sanja Tošić','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'ds2' and c.slug = 'sanja-tosic' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('barter-6','Barter 6','Young Thug',2015,'2010s','300 Entertainment, Atlantic Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Trap']::text[],'Photography by Sandy Kim','<p>The cover of Barter 6 shows Young Thug posing nude against a flat red background, with the title lettering placed low in the frame. It was shot by the photographer Sandy Kim, known for her raw, intimate pictures, and it was her first rap cover. Thug''s team contacted her, and she said much of the concept came from Thug himself.</p><p>Kim told Complex how the shoot came together. When she asked Thug if he would get naked, he replied, "Fuck no, I''m not getting naked, you get naked!" So she did. "Artists should totally be down to commit to the vision they''re asking for, so I got naked and then we shot it," she said, adding that his team was "shooting dice on set." Asked about the suggestive placement of the type, she said, "I think you are meant to [infer] phallic imagery, definitely."</p><p>The image was first unveiled as the cover of Carter 6, a title that borrowed the numbering of Lil Wayne''s Tha Carter series at the height of Wayne''s dispute with Birdman. Wayne mocked rappers who "pose naked on their motherfucking album covers." Under threat of legal action, Thug renamed the tape Barter 6, swapping C for B in the manner of the Bloods, and kept the photograph. In 2023 Lil Uzi Vert recreated the cover for Barter 16, released on Thug''s birthday. The original came out on 17 April 2015.</p>',null,'published','2026-10-30T10:53:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('sandy-kim','Sandy Kim','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'barter-6' and c.slug = 'sandy-kim' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('we-got-it-from-here-thank-you-4-your-service','We Got It from Here... Thank You 4 Your Service','A Tribe Called Quest',2016,'2010s','Epic Records','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Alternative hip-hop','Jazz rap']::text[],'Painting by Richard Prince; art direction by Anita Marisa Boriboon','<p>A Tribe Called Quest''s final album carries a work by the American artist Richard Prince, the painter and photographer famous for appropriating other people''s images. The cover uses an untitled canvas Prince made in 2015, later shown as part of Q-Tip''s own art collection. The packaging was art directed and designed by Anita Marisa Boriboon. The album was recorded at the AbLab, Q-Tip''s home studio in New Jersey.</p><p>The first version was posted by Jarobi White on 3 November 2016. In the corner sat a small kneeling figure painted in red, black and green, the woman from the cover of The Low End Theory, with the group''s logo glowing green above. At the centre a naked woman crouched and photographed herself in front of a grid of boxes. Ambrosia for Heads read it as a picture of the generation gap, with Tribe''s old muse "a bit cowed" beside a louder, more shameless new figure. Prince was known for turning Instagram selfies into art, so the theme fitted his practice.</p><p>Ahead of release, murals tied to the artwork were painted in Melbourne and Sydney. The album came eight months after the death of Phife Dawg, and the cover closes a visual story that began with Tribe''s colour-painted women of the early 1990s. It was released on 11 November 2016.</p>',null,'published','2026-10-30T10:16:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('richard-prince','Richard Prince','Painter') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'we-got-it-from-here-thank-you-4-your-service' and c.slug = 'richard-prince' on conflict do nothing;
insert into public.creators (slug,name,role) values ('anita-marisa-boriboon','Anita Marisa Boriboon','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'we-got-it-from-here-thank-you-4-your-service' and c.slug = 'anita-marisa-boriboon' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('4-44','4:44','Jay-Z',2017,'2010s','Roc Nation','United States','4450e9cf-43d6-481d-b606-2e75cef9e7f9',array['East Coast hip-hop','Conscious hip-hop']::text[],'Art direction by Willo Perron; design by Brian Roettinger','<p>The cover of 4:44 is almost nothing at all: the title in small digits on a soft field of colour somewhere between sand and peach. There is no photograph and no artist name. It was art directed by Willo Perron and designed by Brian Roettinger, the duo behind Jay-Z''s Magna Carta Holy Grail. The digits are set in Larish Neue, a typeface by the Czech designer Radim Peško, first developed for the Secession in Vienna.</p><p>Jay-Z said the title came from the song he called "the crux of the album," written after he woke at 4:44 in the morning. The confessional record needed a quiet face. Perron described the direction as "Stripped down and honest. Simple, not trying to do too much," and summed up the cover in one line: "It''s just this color and these digits." Fonts in Use noted how far the gentle palette sat from the dark, aggressive colours common in rap design.</p><p>The sleeve worked as a logo for a wider campaign. Before release, the cryptic numbers appeared on billboards, buses, taxis and subway stations, and a black-and-white teaser starring Mahershala Ali aired during the NBA Finals. Perron called the brand guide "a manual for the 4:44 brand," and the same restraint shaped the octagonal stage of the tour that followed. Complex judged it the most minimal cover of Jay-Z''s career. The album was released on 30 June 2017.</p>',null,'published','2026-10-30T09:39:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('willo-perron','Willo Perron','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = '4-44' and c.slug = 'willo-perron' on conflict do nothing;
insert into public.creators (slug,name,role) values ('brian-roettinger','Brian Roettinger','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = '4-44' and c.slug = 'brian-roettinger' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('invasion-of-privacy','Invasion of Privacy','Cardi B',2018,'2010s','Atlantic Records, KSR','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Trap','East Coast hip-hop']::text[],'Art direction and design by Nicholas Fulcher; photography by Jora Frantzis','<p>The cover of Invasion of Privacy is a fashion portrait. Cardi B wears a head-to-toe black-and-white check look, a coat and dress from Christian Cowan''s autumn 2018 collection, with Saint Laurent sunglasses and highlighter-yellow hair set in finger waves. The photograph was taken by Jora Frantzis, who later directed Cardi''s "Money" video, and the sleeve was art directed and designed by Nicholas Fulcher. The look was styled by Kollin Carter.</p><p>The finger waves gave the image a 1920s flapper glamour, sharpened by the graphic check and the acid-bright hair. Paper described the scene as Cardi caught by a "voyeuristic video camera," which fits the title. Cardi explained the name herself: "This why I named my album Invasion of Privacy, ''cause people will do the most to be nosey about your life." Rolling Stone linked it to her secret marriage to Offset, which had recently become public. On the cover she gives the cameras exactly what she chooses.</p><p>Cardi revealed the artwork and title on social media on 27 March 2018, and the image spread quickly. Paper called the outfit instantly iconic, and the yellow hair and checked coat became a ready-made costume for fans. The debut went on to win the Grammy for Best Rap Album, and the cover fixed the image of Cardi at the moment she crossed from viral personality to star. The album was released on 6 April 2018.</p>',null,'published','2026-10-30T09:02:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('nicholas-fulcher','Nicholas Fulcher','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'invasion-of-privacy' and c.slug = 'nicholas-fulcher' on conflict do nothing;
insert into public.creators (slug,name,role) values ('jora-frantzis','Jora Frantzis','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'invasion-of-privacy' and c.slug = 'jora-frantzis' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('swimming','Swimming','Mac Miller',2018,'2010s','REMember Music, Warner Bros. Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Alternative hip-hop','Jazz rap']::text[],'Photography by Christian Weber','<p>The cover of Swimming shows Mac Miller sitting on the floor of a small box-like room set in an empty white space, legs stretched out, feet bare and eyes closed. A window is cut into the wall behind him. The photograph was taken by Christian Weber, a photographer born in Cincinnati and raised in Florida, whose agency lists the image as one of his best-known works.</p><p>The album dealt with heartbreak, depression and the effort to keep going, and the cover gives that a physical shape. Mac looks tired and still, boxed in, with an opening to the world just behind him. Fans have pored over the picture for references to his earlier records. Around the release, the designer Todd Hippensteel created a small scuba diver character for the album''s campaign, an image of going under and coming back up that matched the title.</p><p>Mac Miller died a few weeks after the album came out, and the cover took on a weight no one had planned. The diver remained his social media avatar and became one of the most recognisable symbols of his work. The posthumous companion album Circles followed in 2020, and both records were later collected in the Swimming in Circles vinyl box set with photographs from the sessions. Swimming was released on 3 August 2018.</p>',null,'published','2026-10-30T08:25:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('christian-weber','Christian Weber','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'swimming' and c.slug = 'christian-weber' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('bandana','Bandana','Freddie Gibbs & Madlib',2019,'2010s','ESGN, Keep Cool, Madlib Invazion, RCA Records','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['Gangsta rap','Underground hip-hop']::text[],'Illustration by Jeff Jank','<p>The cover of Bandana is a cartoon. Quasimoto, the squeaky-voiced alter ego Madlib created in the late 1990s, sits on a zebra with a bandana around his neck and watches the buildings of Hollywood burn. A smashed piñata lies on the ground. The artwork is by Jeff Jank, Madlib''s longtime collaborator and the designer behind much of the Stones Throw catalogue.</p><p>The image links the album to its predecessor. Freddie Gibbs and Madlib''s first full album, Piñata, came out in 2014, and Flood noted that the zebra repeats a motif from that record, while the broken piñata in the corner signals a sequel. Putting Quasimoto on the front gave the cover to Madlib''s side of the partnership, set against the crime and chaos of Gibbs''s lyrics. A burning skyline seen from the back of a zebra captures the duo''s mix of menace and absurd humour.</p><p>Madlib shared the cover on Twitter on 28 May 2019 with only a zebra emoji. Okayplayer greeted it with "MadGibbs coming with another classic." The same art was kept for the vinyl editions, including a white pressing of 1,000 copies for the Berlin shop HHV. The album was released on 28 June 2019.</p>',null,'published','2026-10-30T07:11:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('jeff-jank','Jeff Jank','Illustrator') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'bandana' and c.slug = 'jeff-jank' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('zuu','ZUU','Denzel Curry',2019,'2010s','PH Recordings, Loma Vista Recordings','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['Southern hip-hop','Trap']::text[],null,'<p>The cover of ZUU is a love letter to Miami in graphic form. It pairs a photograph of Denzel Curry with retro lettering in green and orange, the colours of the University of Miami. Treble described the design as a throwback to 1990s hip-hop sleeves, with a logo that recalls the one on Black Sheep''s debut album. The title itself is a local nickname for Carol City, the Miami Gardens neighbourhood where Curry grew up.</p><p>Curry made the album in Los Angeles while homesick, and he called it "some real Miami stuff." The cover plays up that hometown pride with school colours and old-school type that many Miami fans would recognise at once. Curry had drawn the cover of his early project Nostalgia himself and said he often pictures an album''s artwork before the music is finished. Around the release he also drew a self-portrait for XXL, explaining, "I drew a self portrait because this is the man I am now."</p><p>The retro styling marked a break from the dark, apocalyptic imagery of TA13OO, released the year before. The short, punchy album was received as a tribute to South Florida rap, and the cover''s local references signalled that intent before a note was heard. The album was released on 31 May 2019.</p>',null,'published','2026-10-30T06:34:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('alfredo','Alfredo','Freddie Gibbs & The Alchemist',2020,'2020s','ESGN, ALC Records, Empire','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['Gangsta rap','Boom bap']::text[],'Art direction by Vlad Sepetov','<p>The cover of Alfredo shows a hand working the strings of a marionette, and the puppet is a plate of fettuccine Alfredo. The design is by the art director Vlad Sepetov. The black field and the hovering hand make the reference plain: it borrows the famous puppeteer logo of The Godfather films.</p><p>The joke runs on several levels. The title combines the names of the two artists, Alchemist and Freddie, and lands on a classic Italian-American dish. The Godfather nod frames Gibbs as a mob boss, a role his cold, detailed street narratives often play with. A plate of pasta pulled on strings also suggests control and power behind the scenes, with The Alchemist as the hand. The cover turns a pun into a mafia movie poster in a single image.</p><p>The packaging went further. The release came with a comic book drawn by the comic artist Mike del Mundo, inspired by the album''s songs. Alfredo was nominated for Best Rap Album at the 2021 Grammy Awards, rare recognition for an independent release. The duo returned to the same theme for Alfredo 2 in 2025. The original was released on 29 May 2020.</p>',null,'published','2026-10-30T05:57:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('vlad-sepetov','Vlad Sepetov','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'alfredo' and c.slug = 'vlad-sepetov' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('my-turn','My Turn','Lil Baby',2020,'2020s','Quality Control Music, Motown Records, Capitol Records, Wolfpack Music Group','United States','6cbdce99-93a5-4ccd-adbc-b5e907e3ee7e',array['Trap','Southern hip-hop']::text[],null,'<p>The cover of My Turn is a pastoral painting. Lil Baby sits on top of a large jutting rock surrounded by water, greenery and baby goats, lighting up a smoke that drifts into the haze of the scene. The soft, idealised landscape is a long way from the Atlanta streets his music describes.</p><p>The goats are the clearest sign of intent. In rap, the goat stands for "greatest of all time," and putting baby goats around a rapper called Baby makes the claim twice. The title says the same thing: after years as a hit-making collaborator and featured guest, this was his moment to take the top spot. Choosing a painted, almost classical scene gave the boast a calm, settled feel, closer to a portrait of a landowner than a mugshot.</p><p>Lil Baby revealed the artwork in early January 2020, and Rap-Up and Billboard reported on it on 2 January. He later shared the tracklist with the caption "My Best Work To Date!" The album went straight to number one on the Billboard 200 and became the most consumed album of 2020 in the United States. A deluxe edition followed in May. The album was released on 28 February 2020.</p>',null,'published','2026-10-30T05:20:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('shoot-for-the-stars-aim-for-the-moon','Shoot for the Stars, Aim for the Moon','Pop Smoke',2020,'2020s','Victor Victor Worldwide, Republic Records','United States','464ed954-6e08-4d0e-84ab-1a736b658cd3',array['Brooklyn drill']::text[],'Design by Ryder Ripps','<p>The released cover of Pop Smoke''s posthumous debut is a single chrome rose on a black background. It was made by the conceptual artist Ryder Ripps, and according to Wikipedia it was chosen by Pop Smoke''s mother only hours before the album came out. It replaced an earlier design by Virgil Abloh that lasted barely a day.</p><p>Abloh''s version placed a greyscale photograph of Pop Smoke among metallic roses and barbed wire. He explained it on Instagram: Pop Smoke had told him "his story felt like the metaphor of a rose & thorns growing from the concrete of his hood in Canarsie, Brooklyn." Fans were unmoved. They pointed out that the photograph was the first result on a Google search, called the graphics clip art and the result "lazy," and a petition gathered thousands of signatures. 50 Cent, the album''s executive producer, posted dozens of fan-made alternatives. Ripps then accused Abloh of taking his "entire chrome rose concept" and ruining it with careless design.</p><p>Steven Victor, Pop Smoke''s manager and label head, answered within hours: "Pop would listen to his fans. Making a change." The final cover kept the rose and dropped everything else, a quiet memorial to a 20-year-old rapper killed in February 2020. The album went to number one on the Billboard 200. It was released on 3 July 2020.</p>',null,'published','2026-10-30T04:43:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('ryder-ripps','Ryder Ripps','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'shoot-for-the-stars-aim-for-the-moon' and c.slug = 'ryder-ripps' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('rtj4','RTJ4','Run the Jewels',2020,'2020s','Jewel Runners / BMG','United States','fe0a06f7-7dc0-4ce2-a96b-221dbc0d00d9',array['hardcore hip-hop','political hip-hop']::text[],'Art direction and photography by Tim Saccenti; design by Smartbomb.net; lettering by Nick Gazin','<p>Every Run the Jewels album carries the same emblem: a pointed finger gun and a clenched fist. For RTJ4 the duo made it physical. Photographer and director Tim Saccenti, who had worked with El-P since his second solo album, built the hands as a low poly model and 3D printed them as a glossy sculpture. He then photographed the object under several coloured lights and combined the shots into the final image. Layout and design came from Smartbomb.net, with lettering by Nick Gazin, the illustrator who drew the group''s first two covers.</p><p>El-P said he wanted to make the logo feel futuristic by going back to "some of the most basic shapes." The faceted surfaces turn a hand-drawn symbol into something that looks machined, like a trophy or a game asset. The coloured lights were a deliberate callback: they echo the colour schemes of the earlier albums, so the fourth cover quietly contains the first three. El-P has described the group''s visual side as "sort of an art collective", and the cover shows that process at work, with an illustrator''s mark passed to a photographer and rebuilt in plastic.</p><p>The pistol and fist had become one of the most recognisable logos in modern rap, and RTJ4 gave it its sleekest form. One writer tracking the series called the low poly version possibly his favourite so far. The duo released the album for free download two days ahead of schedule, on 3 June 2020.</p>',null,'published','2026-10-30T04:06:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('tim-saccenti','Tim Saccenti','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'rtj4' and c.slug = 'tim-saccenti' on conflict do nothing;
insert into public.creators (slug,name,role) values ('tim-saccenti','Tim Saccenti','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'rtj4' and c.slug = 'tim-saccenti' on conflict do nothing;
insert into public.creators (slug,name,role) values ('smartbomb-net','Smartbomb.net','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'rtj4' and c.slug = 'smartbomb-net' on conflict do nothing;
insert into public.creators (slug,name,role) values ('nick-gazin','Nick Gazin','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'rtj4' and c.slug = 'nick-gazin' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('king-s-disease','King''s Disease','Nas',2020,'2020s','Mass Appeal Records','United States','464ed954-6e08-4d0e-84ab-1a736b658cd3',array['east coast hip-hop','conscious hip-hop']::text[],'Creative direction by Peter Bittenbender; painting by Harmonia Rosales','<p>Nas commissioned the cover of King''s Disease from Harmonia Rosales, the Afro-Cuban painter known for recasting European religious art with Black figures. She worked digitally, a medium she had only recently taken up, and used the job to test those skills. The brief was loose: the title, and the idea of the "king''s disease" as gluttony. Rosales had full creative control and chose not to hear the music first. A job planned for four days took about two weeks of near constant work. "I took like 4 hours on little things like one part of the crown," she said.</p><p>The result is dense with symbols on a field of red, which Rosales uses for sacrifice. A cracked stone halo hangs behind a throne marked with African signs of greatness. A machete stands for Ogun and bata drums for Chango, both Orishas. Blank souls pick at a crown, people who want a leader''s seat without knowing its cost. Pearls, a snake and a skull trace a life from innocence to knowledge to death, while a dagger drips blood onto a papaya. A boar''s head, grapes turning to wine and a wedding ring point to excess and to Nas''s own life. "I wanted to incorporate the entire lifecycle just like a king would a leader," she said.</p><p>The red and gold scheme carried through the whole King''s Disease series. The album won the Grammy for Best Rap Album, the first of Nas''s career. It was released on 21 August 2020.</p>',null,'published','2026-10-30T03:29:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('peter-bittenbender','Peter Bittenbender','Creative Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'king-s-disease' and c.slug = 'peter-bittenbender' on conflict do nothing;
insert into public.creators (slug,name,role) values ('harmonia-rosales','Harmonia Rosales','Painter') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'king-s-disease' and c.slug = 'harmonia-rosales' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('donda','Donda','Kanye West',2021,'2020s','GOOD Music / Def Jam Recordings','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['gospel rap','progressive rap']::text[],null,'<p>Donda arrived with no image at all. The cover is a plain black square, with no title, no name and no picture. It is the end point of a long run of public false starts. In July 2020 Kanye West posted a proposed cover by Pierre-Louis Auvray: an infrared landscape in orange and red, with figures, a sun and a moon against green mountains and purple clouds. A year later, before the first listening event in Atlanta on 22 July 2021, promotional art used a detail from a 2007 gouache by Louise Bourgeois, a woman in monochrome red with a ponytail flowing behind her.</p><p>West never explained the black square. The album is named after his mother, Donda West, who died in 2007, and black is the colour of mourning, which is how most listeners read it. The emptiness also fits the way the record was made: it was performed in stadiums, rebuilt between events and changed even after release. On the day it appeared, West wrote that Universal had put the album out "without my approval", which suggests the blank cover may have been as much a sign of an unfinished process as a statement.</p><p>The Bourgeois image caused its own stir, since early reports wrongly said North West had drawn it, and Artnet pressed the society representing her estate on whether permission had been given. Days later Drake used a Damien Hirst work for Certified Lover Boy, and the two covers were compared as a contest of fine-art names. Donda was released on 29 August 2021.</p>',null,'published','2026-10-30T02:15:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('the-off-season','The Off-Season','J. Cole',2021,'2020s','Dreamville / Roc Nation / Interscope Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['southern hip-hop','conscious hip-hop']::text[],'Creative direction by Felton Brown; photography by Justin Francis','<p>J. Cole stands in front of a basketball hoop that is on fire. The cover of The Off-Season was photographed by Justin Francis, a photographer, director and cinematographer, and organised by Felton Brown, Dreamville''s creative director. The initial idea came from Dreamville president Ibrahim Hamad, and Brown developed it. Because Cole could not easily travel, the team shot close to home in North Carolina. Brown told Complex they "finished the album artwork two weeks before we announced it."</p><p>Basketball runs through Cole''s whole catalogue. His mixtapes The Warm Up and Friday Night Lights and his debut album Cole World: The Sideline Story all borrowed the language of the sport, and the burning hoop pulls those threads together. The title frames the album as the work done between seasons, the training no one sees, and the flames suggest that work has reached a dangerous heat. The picture is calm and centred, with Cole facing the camera as the rim burns behind him.</p><p>The image landed at a moment when Cole''s basketball ambitions were literal. In the same month the album came out he made his professional debut with the Patriots Basketball Club in the Basketball Africa League, and he became the first musician on the cover of SLAM. The cover reads as a statement of intent from someone treating rap like an athlete treats a career. The Off-Season was released on 14 May 2021.</p>',null,'published','2026-10-30T01:38:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('felton-brown','Felton Brown','Creative Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'the-off-season' and c.slug = 'felton-brown' on conflict do nothing;
insert into public.creators (slug,name,role) values ('justin-francis','Justin Francis','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'the-off-season' and c.slug = 'justin-francis' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('it-s-almost-dry','It''s Almost Dry','Pusha T',2022,'2020s','GOOD Music / Def Jam Recordings','United States','2a9002ef-8700-4b4b-bc97-eae22cc36802',array['coke rap','east coast hip-hop']::text[],'Art direction by Kanye West; artwork by Sterling Ruby','<p>After the stark Whitney Houston bathroom photograph on Daytona, Pusha T turned to fine art. The cover of It''s Almost Dry was made by Sterling Ruby, the Los Angeles artist whose work runs across ceramics, sculpture, textiles, painting and collage, with art direction credited to Kanye West. Pusha revealed it on social media on 19 April 2022, crediting it simply "by #SterlingRuby". The Fader described it as a collage, and the image is crowded with worn surfaces that look like rust, metal or bark, with the title laid across them in warped, shiny lettering.</p><p>The title itself comes from painting. Pusha told Rolling Stone that when people asked when the album would be done, he would answer that it was almost dry, the way a painter talks about a canvas. Hiring a working artist made the joke literal. Ruby''s battered textures also suit the album''s subject, years of drug-trade imagery treated as raw material. One critic called the result "graphically LAWLESS", a cover that refuses the clean luxury look common in rap packaging.</p><p>Ruby made artwork for the singles too, including "Diet Coke" and "Neck &amp; Wrist", which one magazine described as "high energy, partly corroded" works. The set gave the album a consistent look across every release. It was Pusha T''s final album for GOOD Music and Def Jam, and it was released on 22 April 2022.</p>',null,'published','2026-10-30T01:01:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('kanye-west','Kanye West','Art Director') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'it-s-almost-dry' and c.slug = 'kanye-west' on conflict do nothing;
insert into public.creators (slug,name,role) values ('sterling-ruby','Sterling Ruby','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'it-s-almost-dry' and c.slug = 'sterling-ruby' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('i-never-liked-you','I Never Liked You','Future',2022,'2020s','Freebandz / Epic Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['trap','southern hip-hop']::text[],null,'<p>On the cover of I Never Liked You, Future sits in the back seat of a luxury car with a sleep mask over his eyes. His outfit and the car''s interior share a tightly coordinated palette, and the frame is filled edge to edge with leather, fabric and the man himself. One critic estimated the clothes at more than $60,000 and identified the mask as a Derek Rose piece costing $275. The animated version made for Apple Music adds camera flashes bursting against the car window.</p><p>The car is one of rap''s oldest cover settings, a shorthand for arrival and wealth. Future uses it to show the opposite of excitement. He is chauffeured, dressed for a gala and asleep, or pretending to be, while photographers try to catch him through the glass. The writer Sam Thomas called him "exquisitely unbothered" and compared the picture to Jack Harlow''s That''s What They All Say, which uses a similar backseat scene: Harlow looks delighted by success, Future looks long since bored by it. The title supplies the rest. Shutting out the world with a mask is the visual form of a man who never liked you anyway.</p><p>Not every detail landed. The same critic called the stretched Parental Advisory label "a total design botch". The image still became one of Future''s most recognisable covers. The album was released on 29 April 2022, with a deluxe edition following on 2 May.</p>',null,'published','2026-10-30T00:24:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('melt-my-eyez-see-your-future','Melt My Eyez See Your Future','Denzel Curry',2022,'2020s','PH / Loma Vista Recordings','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['conscious hip-hop','jazz rap']::text[],null,'<p>The cover of Melt My Eyez See Your Future shows Denzel Curry''s face dissolving. His features are smeared and stretched, so the portrait seems to run like wet paint, and the colours drift through aqua, teal, indigo and violet against a soft blue ground. Only the outline of his head and his spiky hair hold the image together.</p><p>The picture takes the title literally. Melting eyes become a melting face, and the blur turns a straightforward portrait into something closer to a vision, an image seen through tears or heat. The album was Curry''s most inward record, made after years of loud, aggressive releases, with songs about anger, faith and growth. A sharp, posed photograph would have suited the old persona. A face in the middle of changing suits a record about becoming someone else.</p><p>Curry announced the album on 5 January 2022 with a trailer before revealing the art. A deluxe Extended Edition followed on 30 September 2022 with its own alternate cover. The original was released on 25 March 2022.</p>',null,'published','2026-10-29T23:47:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('the-forever-story','The Forever Story','JID',2022,'2020s','Dreamville / Interscope Records','United States','818f66a4-a51e-4b8b-b515-691d9aba254d',array['southern hip-hop','conscious hip-hop']::text[],null,'<p>The cover of The Forever Story places JID in the middle of a crowd. Around him stand people from all walks of life, and he is one figure among many, at the centre of the frame without towering over it. The image was designed as a sequel, echoing the artwork of his 2017 debut The Never Story, just as the album''s title answers the earlier one.</p><p>The crowd is the point. The Forever Story is JID''s most autobiographical record, built around his family in East Atlanta, his siblings, his parents and the community that raised him. Writers described the cover as capturing "the different realities Black people face in America", and the faces around him work as a cast list for the songs: relatives, neighbours, friends and strangers whose stories run through the verses. Where The Never Story introduced a young rapper on his own terms, the follow-up surrounds him with the people who made him, and the shift from never to forever is mirrored in the move from one figure to many.</p><p>The album arrived five years after The Never Story, a long wait for a Dreamville artist who had become one of the most admired technicians in rap. Critics placed it among the best rap albums of 2022, and the cover''s idea of a life told through a community suited that praise. It was released on 26 August 2022.</p>',null,'published','2026-10-29T23:10:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('cheat-codes','Cheat Codes','Danger Mouse & Black Thought',2022,'2020s','BMG','United States','cac97ec2-47e9-4562-b1b0-ebb5ae534086',array['boom bap','conscious hip-hop']::text[],'Cover art by Jacob Escobedo; layout by Samantha Meadows','<p>The cover of Cheat Codes was made by Jacob Escobedo, with layout by Samantha Meadows. Escobedo is an Atlanta artist and designer who spent years as head of design for the creative group behind Cartoon Network and Adult Swim, and whose illustrations have run in The New Yorker. He is also one of Danger Mouse''s longest visual partners.</p><p>The two met around 2004, and Escobedo designed the cover for DangerDoom''s The Mouse and the Mask, Danger Mouse''s 2005 album with MF DOOM made in partnership with Adult Swim. He went on to work on at least five albums with the producer, including records by Broken Bells, and has also made artwork for The Shins and Vampire Weekend. That history gives Cheat Codes a quiet continuity. The album itself grew from a collaboration with Black Thought first planned around 2005, and it includes a posthumous verse from MF DOOM on "Belize". Hiring the designer of the DangerDoom cover for this record links the two projects visually as well as musically, and keeps Danger Mouse''s records within a small circle of trusted collaborators.</p><p>BMG released the album on vinyl in black and a limited red edition, each with a printed inner sleeve. Critics treated Cheat Codes as a late-career peak for Black Thought, a high watermark for both men. It was released on 12 August 2022.</p>',null,'published','2026-10-29T22:33:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('jacob-escobedo','Jacob Escobedo','Designer') on conflict (slug) do nothing;
