insert into public.creators (slug,name,role) values ('samantha-meadows','Samantha Meadows','Designer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'cheat-codes' and c.slug = 'samantha-meadows' on conflict do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('king-s-disease-iii','King''s Disease III','Nas',2022,'2020s','Mass Appeal Records','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['east coast hip-hop','boom bap']::text[],null,'<p>The third King''s Disease cover is the plainest of the series. Three gold bars sit against a red ground, each engraved with "KD 3". Together they stand in for the Roman numeral III. Below them the release date appears in the same typeface used on the two earlier covers.</p><p>The series began with Harmonia Rosales''s crowded painting of thrones, halos and Orishas, and King''s Disease II stripped that back while keeping the red and gold. The third cover finishes the reduction. All that remains is colour, metal and a number. Gold bullion is an obvious symbol of wealth, and here it reads as a scoreboard: three albums with Hit-Boy, three wins, stacked like reserves in a vault. The engraving makes the bars feel like trophies made for the occasion, and the shared typeface ties the trilogy together on a shelf. AllMusic''s David Crone took the three bullions as a sign of the duo''s continued success, which is exactly how the image asks to be read.</p><p>Nas and Hit-Boy unveiled the artwork on 18 October 2022. Nas captioned the post with the date, 11.11, and the album was billed as the final instalment of the series. It was the pair''s fourth project together after Magic. King''s Disease III was released on 11 November 2022.</p>',null,'published','2026-10-29T21:56:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('michael','Michael','Killer Mike',2023,'2020s','VLNS / Loma Vista Recordings','United States','52e1479f-82f9-46b7-86e4-f22d676e06cc',array['southern hip-hop','gospel rap']::text[],null,'<p>The cover of Michael is a school yearbook photograph of Michael Render at nine years old. Someone has drawn on it: a halo above his head and a pair of devil''s horns. The doodles turn a plain studio portrait from an Atlanta childhood into a small drawing of a split personality.</p><p>Killer Mike chose the image to introduce the person behind the name. It was his first solo album in over a decade, and he framed it as an origin story, built around his grandmother, the church and the streets of Collier Heights. The halo and horns describe the boy he remembers, one he called "that little mischievous" kid "who knows the word of God." Elsewhere he described him as "just a little mischievous, heart-of-gold." The cover holds both sides without choosing, which suits songs that move between sermon and street story. Looking at the photo years later, he joked: "I would''ve named me Handsome Mike!" About the boy himself he was simpler: "That''s me for real."</p><p>Childhood photos are a long tradition on rap covers, from Illmatic onward, but the hand-drawn halo and horns give this one its own voice, closer to a kid defacing his own picture. The album won the Grammy for Best Rap Album in 2024, one of three awards Killer Mike took that night. Michael was released on 16 June 2023.</p>',null,'published','2026-10-29T21:19:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('magic-3','Magic 3','Nas',2023,'2020s','Mass Appeal Records','United States','c0217d82-6644-4ea9-99d1-67b7e9dbe7a7',array['east coast hip-hop','boom bap']::text[],null,'<p>Magic 3 closes the run of albums Nas made with Hit-Boy, and its cover is spare. It is a black-and-white image with white lettering and the Nas logo, a monochrome design that strips away the reds and golds of the King''s Disease series. Nas revealed the artwork on Instagram on 12 September 2023, along with the news that the album would drop on his birthday.</p><p>The timing carried the meaning. Magic 3 arrived on Nas''s 50th birthday, in the same year hip-hop itself was celebrating fifty years, and it was presented as the last chapter of a partnership that had produced six albums in three years. The Magic records were the looser, faster side of that run, released with little warning, and their covers followed suit: quick, graphic and unfussy. A black-and-white cover suits a closing statement. It avoids any sense of a victory parade at the moment the series ends.</p><p>The partnership with Hit-Boy had begun during the pandemic, when, as Nas later recalled, "the world shut down, I wasn''t leaving home, and Hit-Boy was telling me to come out." It had turned into one of the most productive late-career runs in rap. Magic 3 was released on 14 September 2023.</p>',null,'published','2026-10-29T20:42:00+00:00') on conflict (slug) do nothing;
insert into public.covers (slug,title,artist,release_year,decade,label,country,cover_type_id,subgenres,credits_text,description_html,image_url,status,created_at) values ('we-don-t-trust-you','We Don''t Trust You','Future & Metro Boomin',2024,'2020s','Freebandz / Boominati / Epic Records / Republic Records','United States','0eb085f8-d7ea-47e5-8c4a-bf504de1773f',array['trap','southern hip-hop']::text[],'Photography by Matt Adam','<p>The cover of We Don''t Trust You is a dark photograph of Future and Metro Boomin standing together against a black background. One of them carries a briefcase, and Future appears to cover his mouth. The duo dressed in high fashion for the shoot, Future in Lanvin and Metro in Celine, and the photograph is credited to Matt Adam.</p><p>The image works like a film still from a crime story. The briefcase, the shadows and the guarded gesture all point to deals, secrets and silence, which fits a title built on suspicion. Future covering his mouth reads as a refusal to talk, the opposite of the open, confessional mood of a lot of rap promotion. The pair had first worked together a decade earlier, and here they present themselves as partners in something they will not explain. The album''s trailer used the same outfits, so the cover sat inside a wider campaign with a single look.</p><p>The idea extended into a sequel. A few weeks later the pair revealed We Still Don''t Trust You, its cover a black-and-white image shot on 35mm film by Adam, with the duo split across four quadrants, in the same suits and in white with masks. Read together, the two covers form a diptych. The first album debuted on top of the Billboard 200, helped by Kendrick Lamar''s verse on "Like That". We Don''t Trust You was released on 22 March 2024.</p>',null,'published','2026-10-29T20:05:00+00:00') on conflict (slug) do nothing;
insert into public.creators (slug,name,role) values ('matt-adam','Matt Adam','Photographer') on conflict (slug) do nothing;
insert into public.cover_creators (cover_id,creator_id) select v.id, c.id from public.covers v, public.creators c where v.slug = 'we-don-t-trust-you' and c.slug = 'matt-adam' on conflict do nothing;
